1	import java.util.List;
2	import java.util.Random;
3	/**
4	 * A class representing shared characteristics of animals.
5	 *
6	 * @version 1.3
7	 */
8	public abstract class Animal implements Actor
9	{
10	
11	    /*///////////////////////////////////////////////////////////////
12	                                  STATE
13	    //////////////////////////////////////////////////////////////*/
14	
15	    private boolean alive;
16	    private Field field;
17	    private Location location;
18	    private int age;
19	    private final Gender gender;
20	    private int foodLevel;
21	    private Integer infectionTimestamp;
22	
23	    private static final Random rand = Randomizer.getRandom();
24	
25	    /*///////////////////////////////////////////////////////////////
26	                                CONSTRUCTOR
27	    //////////////////////////////////////////////////////////////*/
28	
29	    /**
30	     * Create a new animal at location in field.
31	     *
32	     * @param randomAge flag indicating whether to randomly generate age and foodLevel or not
33	     * @param field The field currently occupied.
34	     * @param location The location within the field.
35	     * @param gender Gender of the animal
36	     * @param baseLevel base food level of an animal
37	     * @param maxAge maximum age the animal can take
38	     */
39	    public Animal(boolean randomAge, Field field, Location location, Gender gender, int baseLevel, int maxAge)
40	    {
41	        if (randomAge) {
42	            this.age = rand.nextInt(maxAge);
43	            this.foodLevel = rand.nextInt(baseLevel);
44	        } else {
45	            this.foodLevel = baseLevel;
46	            this.age = 0;
47	        }
48	        this.alive = true;
49	        this.field = field;
50	        this.gender = gender;
51	        this.infectionTimestamp = null;
52	        setLocation(location);
53	    }
54	
55	    /*///////////////////////////////////////////////////////////////
56	                        ABSTRACT BEHAVIOUR HOOKS
57	    //////////////////////////////////////////////////////////////*/
58	
59	    protected abstract int getMaxAge();
60	    protected abstract int getMaxLitterSize();
61	    protected abstract double getBreedingProbability(Weather weather);
62	    protected abstract int getBreedingAge();
63	    protected abstract Location doFindFood();
64	    protected abstract Animal createOffspring(Field field, Location location, Gender gender);
65	    public abstract int getFeedingValue();
66	
67	    /** Override to return true for animals that skip their turn at night. */
68	    protected boolean isRestrictedToDay() { return false; }
69	
70	    /*///////////////////////////////////////////////////////////////
71	                            ANIMAL BEHAVIOUR LOGIC
72	    //////////////////////////////////////////////////////////////*/
73	
74	    /**
75	     * Make this animal act - that is: make it do
76	     * whatever it wants/needs to do.
77	     *
78	     * @param newAnimals A list to receive newly born animals.
79	     * @param weather The current weather
80	     * @param dayState The different state of the day
81	     */
82	    public void act(List<Actor> newAnimals, Weather weather, DayState dayState)
83	    {
84	        if(isRestrictedToDay() && dayState == DayState.NIGHT) {
85	            return;
86	        }
87	        incrementAge(getMaxAge());
88	        incrementHunger();
89	        if(!isAlive()) {
90	            return;
91	        }
92	        meet(newAnimals, getMaxLitterSize(), getBreedingProbability(weather), getBreedingAge());
93	        Location newLocation = doFindFood();
94	        if(newLocation == null) {
95	            newLocation = field.freeAdjacentLocation(getLocation());
96	        }
97	        if(newLocation != null) {
98	            setLocation(newLocation);
99	        } else {
100	            setDead();
101	        }
102	    }
103	
104	    /**
105	     * Increments the age of the animal.
106	     *
107	     * @param maxAge The maximum age of the animal before he dies.
108	     */
109	    private void incrementAge(int maxAge)
110	    {
111	        age++;
112	        if(age > maxAge) {
113	            setDead();
114	        }
115	    }
116	
117	    /**
118	     * Increment the hunger of the animal.
119	     */
120	    private void incrementHunger()
121	    {
122	        foodLevel--;
123	        if(foodLevel <= 0) {
124	            setDead();
125	        }
126	    }
127	
128	    /**
129	     * Add to the animal's food level (used by herbivores when eating plants).
130	     *
131	     * @param amount the amount to add.
132	     */
133	    protected void addFoodLevel(int amount)
134	    {
135	        foodLevel += amount;
136	    }
137	
138	    /**
139	     * Replace the animal's food level (used by carnivores after making a kill).
140	     *
141	     * @param level the new food level.
142	     */
